function formsSquare(sticks: number[]): boolean {
  const n = sticks.length;
  const sides = [0, 0, 0, 0];
  const go = (i: number): boolean => {
    if (i === n) return sides[0] === sides[1] && sides[1] === sides[2] && sides[2] === sides[3];
    for (let s = 0; s < 4; s++) {
      sides[s] += sticks[i];
      if (go(i + 1)) return true;
      sides[s] -= sticks[i];
    }
    return false;
  };
  return go(0);
}

