function formsSquare(sticks: number[]): boolean {
  const total = sticks.reduce((a, b) => a + b, 0);
  if (total % 4 !== 0) return false;
  const side = total / 4;
  const a = [...sticks].sort((x, y) => y - x);
  if (a[0] > side) return false;
  const sides = [0, 0, 0, 0];
  const go = (i: number): boolean => {
    if (i === a.length) return true;
    const tried = new Set<number>();
    for (let s = 0; s < 4; s++) {
      if (sides[s] + a[i] > side || tried.has(sides[s])) continue;
      tried.add(sides[s]);
      sides[s] += a[i];
      if (go(i + 1)) return true;
      sides[s] -= a[i];
    }
    return false;
  };
  return go(0);
}

