function formsSquare(sticks: number[]): boolean {
  const n = sticks.length;
  const total = sticks.reduce((a, b) => a + b, 0);
  if (total % 4 !== 0) return false;
  const side = total / 4;
  const full = (1 << n) - 1;
  const sum = new Array(1 << n).fill(0);
  const ok = new Array(1 << n).fill(false);
  ok[0] = true;
  for (let mask = 0; mask <= full; mask++) {
    if (mask > 0) {
      const low = mask & -mask;
      sum[mask] = sum[mask ^ low] + sticks[31 - Math.clz32(low)];
    }
    if (!ok[mask]) continue;
    const room = side - (sum[mask] % side);
    for (let i = 0; i < n; i++) {
      if (!(mask & (1 << i)) && sticks[i] <= room) ok[mask | (1 << i)] = true;
    }
  }
  return ok[full];
}

